completion_sequence64.source:
namespace block0 {

template<int... I> struct Seq {};
template<int N> struct Build {
  template<class, int... I> using Map = Seq<I...>;
  using type = __make_integer_seq<Map,int,N>;
};
struct Outer {
  template<class T> struct Inner {
    static int step(int x,int i) { Outer o; Pair p; return (x*(o.factor+p.width)+(i&127))%1009; }
  };
  struct Pair {
    int width;
    template<int... I,int... J> Pair(Seq<I...>,Seq<J...>) : width(sizeof...(I)+sizeof...(J)) {}
    Pair() : Pair(Build<2>::type(),Build<3>::type()) {}
  };
  int factor=12;
};
static_assert(sizeof(Build<3>::type)==1,"member sequence");


}
